components.css:
.ds-retro{color:#d4d9df;font:12px "Courier New",monospace}.ds-transport{display:flex;align-items:center;border:3px groove}.ds-retro button{padding:5px;border-radius:1px}.ds-volume-wrap{display:flex}.ds-retro button:focus-visible,.ds-retro input:focus-visible{outline:2px solid #e6bd68;outline-offset:2px}
.ds-retro .ds-transport{gap:5px;padding:5px;background:linear-gradient(#28313d,#111720);border-color:#7c8797}
.ds-retro .ds-transport button:not(.ds-mute){
 min-width:34px;min-height:32px;color:#15191f;border:2px solid;
 border-color:#e0e3e5 #565d67 #444a53 #b8c0c7;
 background:repeating-linear-gradient(0deg,#ffffff0c 0 1px,#0000000a 1px 2px),linear-gradient(#c5c9cb 0%,#9aa2aa 43%,#7b848e 49%,#aab0b5 100%);
 box-shadow:inset 0 1px 0 #f3f3ec,inset 1px 0 0 #d5dadb,0 2px 3px #0008;
}
.ds-retro .ds-transport button:not(.ds-mute):enabled:hover{background:repeating-linear-gradient(0deg,#ffffff12 0 1px,#00000008 1px 2px),linear-gradient(#e0e2e2,#a1acb6 50%,#c0c7ca);color:#080c10}
.ds-retro .ds-transport button:not(.ds-mute):enabled:active{border-color:#48515a #aeb6bd #cbd1d6 #505962;box-shadow:inset 1px 2px 3px #18202b88}
.ds-retro .ds-transport button.ds-play{min-width:46px;color:#142d08;border-color:#c6e997 #527333 #344d20 #a2bd77;background:repeating-linear-gradient(0deg,#ffffff0a 0 1px,#0000000a 1px 2px),linear-gradient(#a1cc62,#77a93d 46%,#5e8c2c 51%,#8dbb4d);box-shadow:inset 0 1px 0 #dcf1b4,0 2px 3px #0008}
.ds-retro .ds-transport button.ds-play:enabled:hover{background:linear-gradient(#b2db73,#7da940 50%,#a4c965)}
.ds-retro .ds-volume-wrap{
 position:relative;align-self:stretch;align-items:center;gap:5px;padding:3px 9px 3px 7px;min-width:0;
 background:linear-gradient(#25303c,#111923 26%,#111923 76%,#202b38);
 border:1px solid #758190;border-radius:2px;
 box-shadow:inset 0 1px 0 #b5bec8,inset 1px 0 0 #566270,inset 0 -1px 0 #070c12,inset -1px 0 0 #070c12;
}
/* Four domed fasteners sit on the faceplate, outside the usable slider area. */
.ds-retro .ds-volume-wrap::before{
 content:'';position:absolute;inset:0;pointer-events:none;
 --rivet:radial-gradient(circle at 35% 28%,#f0f2ed 0 9%,#b7c1cc 18%,#75818d 39%,#414d59 52%,#141c25 65%,#060b10 73%,transparent 78%);
 background-image:var(--rivet),var(--rivet),var(--rivet),var(--rivet);
 background-size:5px 5px;background-repeat:no-repeat;
 background-position:left 2px top 2px,right 2px top 2px,left 2px bottom 2px,right 2px bottom 2px;
}
.ds-retro .ds-volume-wrap .ds-mute{border:0;box-shadow:none;background:transparent;color:#c6cbd0;min-width:23px;padding:2px}
.ds-retro .ds-volume-wrap .ds-mute:enabled:hover{color:#fff}
.ds-retro .ds-volume{appearance:none;-webkit-appearance:none;width:78px;height:24px;background:transparent;cursor:pointer;flex:1 1 78px;min-width:40px}
.ds-retro .ds-volume::-webkit-slider-runnable-track{height:6px;border:1px inset #606b79;border-radius:0;background:linear-gradient(to right,#8ce430 0 var(--volume-fill,35%),#0b1118 var(--volume-fill,35%) 100%);box-shadow:0 1px 0 #45505c}
.ds-retro .ds-volume::-webkit-slider-thumb{appearance:none;-webkit-appearance:none;width:12px;height:21px;margin-top:-8px;border:2px outset #c5c9ca;border-radius:1px;background:linear-gradient(90deg,#c9cdcd,#7a8490 45%,#2a333f 46% 57%,#9aa4ab 58%,#d1d2d0);box-shadow:1px 2px 3px #0009}
.ds-retro .ds-volume-value{min-width:21px;color:#c4cbd3}
@media(max-width:380px){.ds-retro .ds-transport{gap:3px}.ds-retro .ds-transport button:not(.ds-mute){min-width:29px;padding:4px}.ds-retro .ds-transport button.ds-play{min-width:35px}.ds-retro .ds-volume-wrap{gap:2px;padding-inline:7px}.ds-retro .ds-volume{width:55px}}

